@Component("demandSignal-handler")
@ProcessingGroup("demandSignal-processing-group")
public class DemandSignalEventHandler {
	
	// core constructor
	DemandSignalEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateDemandSignalEvent
     */
    @EventHandler
    public void handle( CreateDemandSignalEvent event) {
        entityManager.persist(new DemandSignal(event.getDemandSignalId(), event.getExternalReference(), event.getRequestedDate(), event.getQuantity(), event.getSku(), event.getReservations(), event.getDemandType()));
    }

    /*
     * @param	event UpdateDemandSignalEvent
     */
    @EventHandler
    public DemandSignal handle( UpdateDemandSignalEvent event) {
    	entityManager.merge(new DemandSignal(event.getDemandSignalId(), event.getExternalReference(), event.getRequestedDate(), event.getQuantity(), event.getSku(), event.getReservations(), event.getDemandType()));
    }
    
    /*
     * @param	event DeleteDemandSignalEvent
     */
    @EventHandler
    public void on( DeleteDemandSignalEvent event) {
    	DemandSignal entity = new DemandSignal();
   
    	// ------------------------------------------
    	// apply the DemandSignalId
    	// ------------------------------------------
    	entity.setDemandSignalId( event.getDemandSignalId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final DemandSignalRepository demandSignalEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(DemandSignalEventHandler.class.getName());

}
